def _family_has_user(family: FamilyGroup, user: User) -> bool:
    return FamilyMembership.objects.filter(
        family=family, user=user, is_active=True
    ).exists()


def _resolve_care_subject_for_medication_bundle(
    *,
    family: FamilyGroup,
    care_subject: Any | None = None,
    care_subject_type: Any = None,
    care_subject_id: Any = None,
    care_subject_name: Any = None,
) -> Any | None:
    if care_subject is not None:
        if isinstance(care_subject, Pet) and care_subject.family_id != family.id:
            raise ValueError("Selected care subject does not belong to this family.")
        if isinstance(care_subject, User) and not _family_has_user(
            family, care_subject
        ):
            raise ValueError("Selected care subject does not belong to this family.")
        return care_subject

    normalized_type = str(care_subject_type or "").strip().lower()
    normalized_id = str(care_subject_id or "").strip()
    if normalized_id:
        if normalized_type in {"person", "user", "family_member", "adult", "elder"}:
            user = User.objects.get(id=normalized_id)
            if not _family_has_user(family, user):
                raise User.DoesNotExist
            return user
        if normalized_type in {"", "pet", "animal"}:
            return Pet.objects.get(id=normalized_id, family=family)

    normalized_name = str(care_subject_name or "").strip()
    if normalized_name:
        if normalized_type in {"person", "user", "family_member", "adult", "elder"}:
            return (
                User.objects.filter(
                    family_memberships__family=family,
                    family_memberships__is_active=True,
                )
                .filter(
                    Q(first_name__iexact=normalized_name)
                    | Q(username__iexact=normalized_name)
                )
                .first()
            )
        return Pet.objects.filter(family=family, name__iexact=normalized_name).first()

    return None


def _current_timezone(timezone_name: str | None = None) -> tzinfo:
    if timezone_name:
        try:
            return ZoneInfo(timezone_name)
        except ZoneInfoNotFoundError:
            logger.warning("Unknown medication timezone %s", timezone_name)
    current_tz = timezone.get_current_timezone()
    return cast(tzinfo, current_tz)


def _coerce_aware_datetime(value: Any, *, default_tz: tzinfo) -> dt_datetime | None:
    if value is None or value == "":
        return None
    if isinstance(value, dt_datetime):
        parsed = value
    else:
        parsed = parse_datetime(str(value))
    if parsed is None:
        return None
    if timezone.is_naive(parsed):
        parsed = parsed.replace(tzinfo=default_tz)
    return parsed.astimezone(default_tz)


def _parse_positive_int(value: Any) -> int | None:
    if value is None or value == "":
        return None
    try:
        parsed = int(float(str(value).strip()))
    except (TypeError, ValueError):
        return None
    return parsed if parsed > 0 else None


def _truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "on"}


def _parse_time_only(value: Any) -> tuple[int, int] | None:
    text = str(value or "").strip()
    if not text:
        return None
    invalid_time_match = INVALID_COLON_TIME_RE.search(text)
    if invalid_time_match is not None:
        minute_text = invalid_time_match.group("minute")
        if len(minute_text) != 2 or int(minute_text) > 59:
            return None
    match = TIME_ONLY_RE.search(text)
    if match is None:
        return None
    hour = int(match.group("hour"))
    minute = int(match.group("minute") or "0")
    ampm = str(match.group("ampm") or "").lower().replace(".", "")
    if ampm == "pm" and hour < 12:
        hour += 12
    elif ampm == "am" and hour == 12:
        hour = 0
    if not ampm and hour > 23:
        return None
    return hour, minute


def _raw_medication_text_chunks(raw_text: str) -> list[str]:
    chunks: list[str] = []
    current: list[str] = []
    for raw_line in raw_text.splitlines():
        line = raw_line.strip(" \t|-")
        if not line:
            continue
        starts_medication = bool(MEDICATION_HEADER_RE.search(line))
        if starts_medication and current:
            chunks.append(" ".join(current))
            current = [line]
        else:
            current.append(line)
    if current:
        chunks.append(" ".join(current))
    return chunks


def _extract_medications_from_text(raw_text: Any) -> list[dict[str, Any]]:
    text = str(raw_text or "").strip()
    if not text:
        return []

    parsed_medications: list[dict[str, Any]] = []
    for chunk in _raw_medication_text_chunks(text):
        name_match = MEDICATION_HEADER_RE.search(chunk)
        interval_match = MEDICATION_INTERVAL_RE.search(chunk)
        next_due_match = MEDICATION_NEXT_DUE_RE.search(chunk)
        if name_match is None or (interval_match is None and next_due_match is None):
            continue

        medication_name = name_match.group("name").strip()
        dosage_text = ""
        dose_match = MEDICATION_DOSE_RE.search(chunk)
        if dose_match is not None:
            dosage_text = dose_match.group("dose").strip()

        min_interval_hours: int | None = None
        max_interval_hours: int | None = None
        if interval_match is not None:
            exact_interval = interval_match.group("exact")
            min_interval_hours = _parse_positive_int(
                exact_interval or interval_match.group("min")
            )
            max_interval_hours = _parse_positive_int(
                exact_interval or interval_match.group("max")
            )
            if min_interval_hours and max_interval_hours is None:
                max_interval_hours = min_interval_hours

        parsed_medications.append(
            {
                "medication_name": medication_name,
                "dosage_text": dosage_text,
                "instructions": chunk,
                "next_due_text": (
                    next_due_match.group("due").strip()
                    if next_due_match is not None
                    else ""
                ),
                "min_interval_hours": min_interval_hours,
                "max_interval_hours": max_interval_hours,
                "is_as_needed": bool(MEDICATION_AS_NEEDED_RE.search(chunk)),
                "confidence": 0.5,
                "source": "raw_text",
            }
        )
    return parsed_medications


def _iso(value: dt_datetime | None) -> str | None:
    return value.isoformat() if value is not None else None


def _format_medication_title(
    *, medication_name: str, dosage_text: str, care_subject: Any | None
) -> str:
    pieces = ["Give", medication_name.strip()]
    if dosage_text.strip():
        pieces.append(dosage_text.strip())
    subject_name = _care_subject_name(care_subject)
    if subject_name:
        pieces.extend(["to", subject_name])
    return " ".join(piece for piece in pieces if piece).strip() or "Give medication"


def _resolve_next_due_window(
    *,
    next_due_text: Any,
    due_at_value: Any = None,
    min_interval_hours: int | None = None,
    max_interval_hours: int | None = None,
    now: dt_datetime,
    default_tz: tzinfo,
) -> tuple[dt_datetime | None, dt_datetime | None, dt_datetime | None, list[str]]:
    warnings_list: list[str] = []
    explicit_due_at = _coerce_aware_datetime(due_at_value, default_tz=default_tz)
    if explicit_due_at is not None:
        window_start = explicit_due_at
    else:
        time_parts = _parse_time_only(next_due_text)
        if time_parts is None:
            if str(next_due_text or "").strip():
                warnings_list.append(
                    f"Needs review: could not turn {next_due_text!s} into an exact reminder time."
                )
            return None, None, None, warnings_list
        local_now = now.astimezone(default_tz)
        candidate = local_now.replace(
            hour=time_parts[0],
            minute=time_parts[1],
            second=0,
            microsecond=0,
        )
        if candidate <= local_now:
            candidate += timedelta(days=1)
        window_start = candidate
        warnings_list.append(
            f"Assumed {next_due_text} means {candidate.date().isoformat()} in the family timezone."
        )

    due_at = window_start
    if (
        max_interval_hours
        and min_interval_hours
        and max_interval_hours > min_interval_hours
    ):
        window_end = window_start + timedelta(
            hours=max_interval_hours - min_interval_hours
        )
    else:
        window_end = window_start
    return window_start, due_at, window_end, warnings_list


def _range_state(*, is_as_needed: bool, has_window: bool) -> str:
    if is_as_needed and has_window:
        return "available"
    if has_window:
        return "due_around"
    return "needs_time"


def prepare_medication_task_bundle(
    *,
    family: FamilyGroup,
    created_by: User | None,
    source: str,
    extracted: dict[str, Any],
    care_subject: Any | None = None,
    care_subject_type: Any = None,
    care_subject_id: Any = None,
    care_subject_name: Any = None,
    now: dt_datetime | None = None,
    timezone_name: str | None = None,
) -> dict[str, Any]:
    default_tz = _current_timezone(timezone_name)
    local_now = (now or timezone.now()).astimezone(default_tz)
    resolved_care_subject = _resolve_care_subject_for_medication_bundle(
        family=family,
        care_subject=care_subject,
        care_subject_type=care_subject_type or extracted.get("care_subject_type"),
        care_subject_id=care_subject_id or extracted.get("care_subject_id"),
        care_subject_name=care_subject_name or extracted.get("care_subject_name"),
    )
    raw_medications = (
        extracted.get("medications")
        or extracted.get("medication_entries")
        or extracted.get("suggested_medications")
        or []
    )
    if not raw_medications:
        raw_medications = _extract_medications_from_text(
            extracted.get("raw_text")
            or extracted.get("text")
            or extracted.get("visible_text")
            or extracted.get("processing_notes")
        )
    if isinstance(raw_medications, dict):
        raw_medications = [raw_medications]

    medications: list[dict[str, Any]] = []
    task_drafts: list[dict[str, Any]] = []
    warnings_list: list[str] = []

    for index, raw_medication in enumerate(raw_medications, start=1):
        if not isinstance(raw_medication, dict):
            continue
        medication_name = str(
            raw_medication.get("medication_name")
            or raw_medication.get("name")
            or raw_medication.get("title")
            or ""
        ).strip()
        dosage_text = str(
            raw_medication.get("dosage_text")
            or raw_medication.get("dose")
            or raw_medication.get("dosage")
            or ""
        ).strip()
        instructions = str(
            raw_medication.get("instructions")
            or raw_medication.get("notes")
            or raw_medication.get("directions")
            or ""
        ).strip()
        if not medication_name:
            continue
        min_interval_hours = _parse_positive_int(
            raw_medication.get("min_interval_hours")
            or raw_medication.get("interval_hours_min")
        )
        max_interval_hours = _parse_positive_int(
            raw_medication.get("max_interval_hours")
            or raw_medication.get("interval_hours_max")
        )
        if min_interval_hours and max_interval_hours is None:
            max_interval_hours = min_interval_hours
        if (
            min_interval_hours
            and max_interval_hours
            and max_interval_hours < min_interval_hours
        ):
            warnings_list.append(
                f"Needs review: interval range for {medication_name} was reversed."
            )
            min_interval_hours, max_interval_hours = (
                max_interval_hours,
                min_interval_hours,
            )
        is_as_needed = _truthy(raw_medication.get("is_as_needed")) or (
            "as needed" in instructions.lower()
        )
        window_start, preferred_due, window_end, due_warnings = (
            _resolve_next_due_window(
                next_due_text=raw_medication.get("next_due_text")
                or raw_medication.get("next_due")
                or raw_medication.get("due_text"),
                due_at_value=raw_medication.get("due_at"),
                min_interval_hours=min_interval_hours,
                max_interval_hours=max_interval_hours,
                now=local_now,
                default_tz=default_tz,
            )
        )
        warnings_list.extend(due_warnings)
        cadence_kind = FamilyTaskSeries.CadenceKind.UNKNOWN
        if min_interval_hours and max_interval_hours:
            cadence_kind = (
                FamilyTaskSeries.CadenceKind.EXACT_INTERVAL
                if min_interval_hours == max_interval_hours
                else FamilyTaskSeries.CadenceKind.FLEXIBLE_INTERVAL
            )
        medication_payload = {
            "draft_id": f"med-{index}",
            "medication_name": medication_name,
            "dosage_text": dosage_text,
            "instructions": instructions,
            "min_interval_hours": min_interval_hours,
            "max_interval_hours": max_interval_hours,
            "cadence_kind": cadence_kind,
            "is_as_needed": is_as_needed,
            "end_condition": str(raw_medication.get("end_condition") or "").strip(),
            "raw": raw_medication,
        }
        medications.append(medication_payload)

        draft_warnings = list(due_warnings)
        title = _format_medication_title(
            medication_name=medication_name,
            dosage_text=dosage_text,
            care_subject=resolved_care_subject,
        )
        notes_parts = [part for part in [instructions, dosage_text] if part]
        reminder_kind = (
            FamilyTaskReminder.Kind.WINDOW_OPEN
            if is_as_needed
            else FamilyTaskReminder.Kind.PREFERRED
        )
        task_drafts.append(
            {
                "draft_id": f"med-{index}-occ-1",
                "series_draft_id": medication_payload["draft_id"],
                "selected": True,
                "title": title,
                "notes": "\n".join(notes_parts),
                "medication_name": medication_name,
                "dosage_text": dosage_text,
                "instructions": instructions,
                "care_subject_id": (
                    str(resolved_care_subject.id)
                    if resolved_care_subject is not None
                    else None
                ),
                "care_subject_type": (
                    _care_subject_summary(resolved_care_subject) or {}
                ).get("type"),
                "care_subject_name": _care_subject_name(resolved_care_subject),
                "care_subject": _care_subject_summary(resolved_care_subject),
                "due_window_start_at": _iso(window_start),
                "due_at": _iso(preferred_due),
                "due_window_end_at": _iso(window_end),
                "min_interval_hours": min_interval_hours,
                "max_interval_hours": max_interval_hours,
                "cadence_kind": cadence_kind,
                "is_as_needed": is_as_needed,
                "range_state": _range_state(
                    is_as_needed=is_as_needed, has_window=window_start is not None
                ),
                "warnings": draft_warnings,
                "reminder_options": [
                    {
                        "kind": reminder_kind,
                        "enabled": False,
                        "remind_at": _iso(
                            window_start
                            if reminder_kind == FamilyTaskReminder.Kind.WINDOW_OPEN
                            else preferred_due
                        ),
                    }
                ],
                "confidence": raw_medication.get("confidence"),
            }
        )

    preview_text = "No medication tasks found"
    if task_drafts:
        preview_text = " | ".join(draft["title"] for draft in task_drafts[:2])[:140]

    return {
        "kind": "medication_task_bundle",
        "version": 1,
        "source": source,
        "family_id": str(family.id),
        "created_by_id": str(created_by.id) if created_by is not None else None,
        "timezone": getattr(default_tz, "key", str(default_tz)),
        "care_subject": _care_subject_summary(resolved_care_subject),
        "medications": medications,
        "task_drafts": task_drafts,
        "warnings": warnings_list,
        "preview_text": preview_text,
        "suggested_kind": "medication_tasks",
    }


def _parse_bundle_datetime(
    value: Any, *, timezone_name: str | None = None
) -> dt_datetime | None:
    return _coerce_aware_datetime(value, default_tz=_current_timezone(timezone_name))


EDITABLE_MEDICATION_DRAFT_FIELDS = {
    "selected",
    "title",
    "notes",
    "due_window_start_at",
    "due_at",
    "due_window_end_at",
    "care_subject_id",
    "care_subject_type",
    "care_subject_name",
    "reminders_enabled",
    "reminder_options",
}


def _merge_reviewed_medication_drafts(
    bundle: dict[str, Any],
    reviewed_tasks: list[dict[str, Any]] | None,
) -> list[dict[str, Any]]:
    canonical_drafts = [
        dict(draft)
        for draft in bundle.get("task_drafts", [])
        if isinstance(draft, dict)
    ]
    if reviewed_tasks is None:
        return canonical_drafts

    by_draft_id = {
        str(draft.get("draft_id")): draft
        for draft in canonical_drafts
        if str(draft.get("draft_id") or "").strip()
    }
    merged_drafts: list[dict[str, Any]] = []
    for index, reviewed in enumerate(reviewed_tasks):
        if not isinstance(reviewed, dict):
            continue
        draft_id = str(reviewed.get("draft_id") or "").strip()
        base = dict(by_draft_id.get(draft_id) or {})
        if not base and index < len(canonical_drafts):
            base = dict(canonical_drafts[index])
        if not base:
            base = dict(reviewed)
        for field in EDITABLE_MEDICATION_DRAFT_FIELDS:
            if field in reviewed:
                base[field] = reviewed[field]
        merged_drafts.append(base)
    return merged_drafts


def _validate_medication_interval(
    *, min_interval_hours: int | None, max_interval_hours: int | None
) -> None:
    if (
        min_interval_hours is not None
        and max_interval_hours is not None
        and max_interval_hours < min_interval_hours
    ):
        raise TaskCaptureCreateError(
            "Medication interval ranges need the minimum before the maximum."
        )


def _validate_medication_window(
    *,
    window_start: dt_datetime | None,
    preferred_due: dt_datetime | None,
    window_end: dt_datetime | None,
) -> None:
    if (
        window_start is not None
        and preferred_due is not None
        and preferred_due < window_start
    ):
        raise TaskCaptureCreateError(
            "Medication dose windows need start, preferred, and end in order."
        )
    if (
        preferred_due is not None
        and window_end is not None
        and window_end < preferred_due
    ):
        raise TaskCaptureCreateError(
            "Medication dose windows need start, preferred, and end in order."
        )
    if (
        window_start is not None
        and window_end is not None
        and window_end < window_start
    ):
        raise TaskCaptureCreateError(
            "Medication dose windows need start, preferred, and end in order."
        )


def _reminder_time_for_kind(
    *, kind: str, task: FamilyTask, fallback: dt_datetime | None
) -> dt_datetime | None:
    if kind == FamilyTaskReminder.Kind.WINDOW_OPEN:
        return task.due_window_start_at or task.due_at or fallback
    if kind == FamilyTaskReminder.Kind.LAST_CALL:
        return task.due_window_end_at or task.due_at or fallback
    return task.due_at or task.due_window_start_at or fallback


def _create_task_reminder(
    *,
    task: FamilyTask,
    user: User,
    kind: str,
    remind_at: dt_datetime,
    created_by: User | None,
) -> FamilyTaskReminder:
    reminder, _created = FamilyTaskReminder.objects.get_or_create(
        family=task.family,
        task=task,
        user=user,
        kind=kind,
        remind_at=remind_at,
        defaults={"created_by": created_by},
    )
    return reminder


def _create_reminders_from_draft(
    *,
    task: FamilyTask,
    draft: dict[str, Any],
    created_by: User | None,
    default_recipient: User | None,
) -> None:
    if default_recipient is None:
        return
    enabled = bool(draft.get("reminders_enabled"))
    reminder_options = draft.get("reminder_options")
    if isinstance(reminder_options, list):
        enabled = enabled or any(
            isinstance(option, dict) and bool(option.get("enabled"))
            for option in reminder_options
        )
    if not enabled:
        return

    kinds: list[str] = []
    if isinstance(reminder_options, list):
        kinds.extend(
            str(option.get("kind") or "")
            for option in reminder_options
            if isinstance(option, dict) and option.get("enabled", True)
        )
    if not kinds:
        kinds.append(
            FamilyTaskReminder.Kind.WINDOW_OPEN
            if task.task_series and task.task_series.is_as_needed
            else FamilyTaskReminder.Kind.PREFERRED
        )

    for kind in kinds:
        if kind not in FamilyTaskReminder.Kind.values:
            continue
        remind_at = _reminder_time_for_kind(kind=kind, task=task, fallback=task.due_at)
        if remind_at is None:
            continue
        _create_task_reminder(
            task=task,
            user=default_recipient,
            kind=kind,
            remind_at=remind_at,
            created_by=created_by,
        )


@transaction.atomic
def materialize_medication_task_bundle(
    *,
    family: FamilyGroup,
    created_by: User | None,
    bundle: dict[str, Any],
    reviewed_tasks: list[dict[str, Any]] | None = None,
    source_client_app: str = ClientApp.ORGANIZE,
    source_object: Any = None,
    default_reminder_recipient: User | None = None,
) -> tuple[list[FamilyTaskSeries], list[FamilyTask]]:
    drafts = _merge_reviewed_medication_drafts(bundle, reviewed_tasks)
    selected_drafts = [
        draft
        for draft in drafts
        if draft.get("selected", True) and str(draft.get("title") or "").strip()
    ]
    if not selected_drafts:
        raise TaskCaptureCreateError("Select at least one medication task to create.")

    medications_by_id = {
        str(medication.get("draft_id")): medication
        for medication in bundle.get("medications", [])
        if isinstance(medication, dict)
    }
    series_by_draft_id: dict[str, FamilyTaskSeries] = {}
    created_series: list[FamilyTaskSeries] = []
    created_tasks: list[FamilyTask] = []
    bundle_timezone = str(bundle.get("timezone") or "").strip() or None

    for draft in selected_drafts:
        bundle_subject = bundle.get("care_subject")
        bundle_subject_id = (
            bundle_subject.get("id") if isinstance(bundle_subject, dict) else None
        )
        bundle_subject_type = (
            bundle_subject.get("type") if isinstance(bundle_subject, dict) else None
        )
        care_subject = _resolve_care_subject_for_medication_bundle(
            family=family,
            care_subject_type=draft.get("care_subject_type") or bundle_subject_type,
            care_subject_id=draft.get("care_subject_id") or bundle_subject_id,
            care_subject_name=draft.get("care_subject_name"),
        )
        series_draft_id = str(draft.get("series_draft_id") or draft.get("draft_id"))
        medication = medications_by_id.get(series_draft_id, {})
        if series_draft_id in series_by_draft_id:
            series = series_by_draft_id[series_draft_id]
        else:
            medication_name = str(
                draft.get("medication_name") or medication.get("medication_name") or ""
            ).strip()
            dosage_text = str(
                draft.get("dosage_text") or medication.get("dosage_text") or ""
            ).strip()
            instructions = str(
                draft.get("instructions") or medication.get("instructions") or ""
            ).strip()
            min_interval_hours = _parse_positive_int(
                draft.get("min_interval_hours") or medication.get("min_interval_hours")
            )
            max_interval_hours = _parse_positive_int(
                draft.get("max_interval_hours") or medication.get("max_interval_hours")
            )
            _validate_medication_interval(
                min_interval_hours=min_interval_hours,
                max_interval_hours=max_interval_hours,
            )
            series = FamilyTaskSeries.objects.create(
                family=family,
                title=f"{medication_name or draft['title']} schedule",
                medication_name=medication_name,
                dosage_text=dosage_text,
                instructions=instructions,
                min_interval_hours=min_interval_hours,
                max_interval_hours=max_interval_hours,
                cadence_kind=str(
                    draft.get("cadence_kind")
                    or medication.get("cadence_kind")
                    or FamilyTaskSeries.CadenceKind.UNKNOWN
                ),
                is_as_needed=bool(
                    draft.get("is_as_needed") or medication.get("is_as_needed")
                ),
                end_condition=str(
                    draft.get("end_condition") or medication.get("end_condition") or ""
                ).strip(),
                raw_schedule=medication or draft,
                created_by=created_by,
                source_client_app=canonicalize_client_app(
                    source_client_app, default=""
                ),
                **_care_subject_relation_kwargs(care_subject),
            )
            if source_object is not None:
                series.source_object = source_object
                series.save(
                    update_fields=[
                        "source_content_type",
                        "source_object_id",
                        "updated_at",
                    ]
                )
            series_by_draft_id[series_draft_id] = series
            created_series.append(series)

        due_window_start_at = _parse_bundle_datetime(
            draft.get("due_window_start_at"), timezone_name=bundle_timezone
        )
        due_at = _parse_bundle_datetime(
            draft.get("due_at"), timezone_name=bundle_timezone
        )
        due_window_end_at = _parse_bundle_datetime(
            draft.get("due_window_end_at"), timezone_name=bundle_timezone
        )
        _validate_medication_window(
            window_start=due_window_start_at,
            preferred_due=due_at,
            window_end=due_window_end_at,
        )
        task = FamilyTask.objects.create(
            family=family,
            title=str(draft["title"]).strip(),
            notes=str(draft.get("notes") or "").strip(),
            status=FamilyTask.Status.PENDING,
            due_window_start_at=due_window_start_at,
            due_at=due_at,
            due_window_end_at=due_window_end_at,
            task_series=series,
            created_by=created_by,
            source_client_app=canonicalize_client_app(source_client_app, default=""),
            task_kind=FamilyTask.TaskKind.MEDICATION,
            **_care_subject_relation_kwargs(care_subject),
        )
        if source_object is not None:
            task.source_object = source_object
            task.save(
                update_fields=[
                    "source_content_type",
                    "source_object_id",
                    "updated_at",
                ]
            )
        _create_reminders_from_draft(
            task=task,
            draft=draft,
            created_by=created_by,
            default_recipient=default_reminder_recipient,
        )
        created_tasks.append(task)

    return created_series, created_tasks


def get_capture_proposals(capture: InboxCapture) -> list[dict[str, Any]]:
    payload = capture.normalized_payload or {}
    raw_proposals = payload.get("proposals")
    if isinstance(raw_proposals, dict):
        proposals = [raw_proposals]
    elif isinstance(raw_proposals, list):
        proposals = [
            proposal for proposal in raw_proposals if isinstance(proposal, dict)
        ]
    else:
        proposals = []

    if proposals:
        return proposals

    task_drafts = payload.get("task_drafts")
    if payload.get("kind") == "medication_task_bundle" and isinstance(
        task_drafts, list
    ):
        medication_proposals = [
            {"kind": "task", **draft}
            for draft in task_drafts
            if isinstance(draft, dict) and str(draft.get("title") or "").strip()
        ]
        if medication_proposals:
            return medication_proposals

    suggested_tasks = payload.get("suggested_tasks")
    if isinstance(suggested_tasks, list):
        task_proposals = [
            {"kind": "task", **task}
            for task in suggested_tasks
            if isinstance(task, dict)
            and str(task.get("title") or task.get("name") or "").strip()
        ]
        if task_proposals:
            return task_proposals

    suggested_items = payload.get("suggested_items")
    if isinstance(suggested_items, list) and suggested_items:
        return [
            {
                "kind": "list",
                "suggested_title": payload.get("suggested_title") or "Shopping list",
                "suggested_items": suggested_items,
            }
        ]

    return []


def get_capture_proposal(
    capture: InboxCapture, *, proposal_index: int = 0
) -> dict[str, Any]:
    proposals = get_capture_proposals(capture)
    if proposal_index < 0 or proposal_index >= len(proposals):
        return {}
    return proposals[proposal_index]


def normalize_capture_target_kind(kind: Any) -> str:
    normalized = str(kind or "").strip().lower()
    if normalized in {"list", "lists", "shopping_list", "grocery", "grocery_list"}:
        return "grocery_list"
    if normalized in {"event", "calendar_event", "appointment", "ics"}:
        return "event"
    return "task"


def infer_capture_target_kind(
    capture: InboxCapture, proposal: dict[str, Any] | None = None
) -> str:
    payload = capture.normalized_payload or {}
    proposal = proposal or {}
    explicit_kind = (
        proposal.get("kind")
        or proposal.get("target_kind")
        or proposal.get("suggested_kind")
        or payload.get("classification")
        or payload.get("suggested_kind")
    )
    if explicit_kind:
        inferred = normalize_capture_target_kind(explicit_kind)
        if inferred != "task" or str(explicit_kind).strip().lower() in {
            "task",
            "tasks",
        }:
            return inferred

    if proposal.get("starts_at") or proposal.get("start_time") or proposal.get("uid"):
        return "event"
    if proposal.get("suggested_items") or proposal.get("items"):
        return "grocery_list"
    return "task"


def _clean_string(value: Any) -> str:
    return str(value or "").strip()


def _proposal_title(proposal: dict[str, Any]) -> str:
    return _clean_string(
        proposal.get("title")
        or proposal.get("summary")
        or proposal.get("suggested_title")
        or proposal.get("name")
    )


def _proposal_notes(proposal: dict[str, Any]) -> str:
    return _clean_string(proposal.get("notes") or proposal.get("description"))


def build_capture_task_payload(
    capture: InboxCapture,
    *,
    proposal_index: int = 0,
    title: str | None = None,
    notes: str | None = None,
) -> dict[str, str]:
    proposal = get_capture_proposal(capture, proposal_index=proposal_index)
    payload = capture.normalized_payload or {}
    task_title = (
        _clean_string(title)
        or _proposal_title(proposal)
        or _clean_string(payload.get("suggested_title"))
        or _clean_string(capture.raw_text)
        or "Inbox item"
    )
    task_notes = (
        _clean_string(notes)
        if notes is not None
        else _proposal_notes(proposal) or _clean_string(capture.raw_text)
    )
    return {"title": task_title, "notes": task_notes}


def _capture_description(
    capture: InboxCapture, proposal: dict[str, Any], notes: str | None
) -> str:
    if notes is not None:
        return _clean_string(notes)
    return _proposal_notes(proposal) or _clean_string(capture.raw_text)


def build_capture_list_payload(
    capture: InboxCapture,
    *,
    proposal_index: int = 0,
    title: str | None = None,
    notes: str | None = None,
    items: list[str] | None = None,
) -> dict[str, Any]:
    proposal = get_capture_proposal(capture, proposal_index=proposal_index)
    payload = capture.normalized_payload or {}
    raw_items: Any = items
    if raw_items is None:
        raw_items = proposal.get("items") or proposal.get("suggested_items")
        if not isinstance(raw_items, list):
            raw_items = payload.get("suggested_items", [])
    items = [_clean_string(item) for item in raw_items if _clean_string(item)]
    return {
        "name": (
            _clean_string(title)
            or _proposal_title(proposal)
            or _clean_string(payload.get("suggested_title"))
            or "Shopping list"
        ),
        "description": _capture_description(capture, proposal, notes),
        "items": items,
    }


def build_capture_event_payload(
    capture: InboxCapture,
    *,
    proposal_index: int = 0,
    title: str | None = None,
    notes: str | None = None,
    starts_at: str | None = None,
    ends_at: str | None = None,
    location: str | None = None,
) -> dict[str, Any]:
    proposal = dict(get_capture_proposal(capture, proposal_index=proposal_index))
    if title is not None and title.strip():
        proposal["summary"] = title.strip()
    if notes is not None:
        proposal["description"] = notes.strip()
    if starts_at is not None and starts_at.strip():
        proposal["starts_at"] = starts_at.strip()
    if ends_at is not None and ends_at.strip():
        proposal["ends_at"] = ends_at.strip()
    if location is not None:
        proposal["location"] = location.strip()
    return proposal


def notify_capture_needs_review(capture: InboxCapture) -> None:
    from django.contrib.contenttypes.models import ContentType

    from notifications.models import Notification
    from notifications.services.notification_service import NotificationService

    content_type = ContentType.objects.get_for_model(capture)
    preview_text = get_capture_preview_text(capture)
    users = (
        User.objects.filter(family_memberships__family=capture.family)
        .filter(family_memberships__is_active=True)
        .distinct()
    )
    for user in users:
        already_notified = Notification.objects.filter(
            user=user,
            content_type=content_type,
            object_id=str(capture.pk),
            data__type="inbox_capture_needs_review",
        ).exists()
        if already_notified:
            continue
        NotificationService.create_user_action_notification(
            user,
            title="Inbox item needs review",
            message=preview_text,
            source_object=capture,
            priority="MEDIUM",
            data={
                "type": "inbox_capture_needs_review",
                "capture_id": str(capture.pk),
                "classification": capture.classification_label,
                "source_email": capture.source_email,
            },
        )


class TaskPhotoProcessingError(ValueError):
    pass


class TaskCaptureCreateError(ValueError):
    def __init__(self, detail: str) -> None:
        super().__init__(detail)
        self.detail = detail


class TaskPhotoExtractionService:
    FEATURE_FLAG_KEY = "enable-ai-task-extraction"
    DEFAULT_MAX_IMAGE_SIZE_BYTES = 10 * 1024 * 1024
    DEFAULT_MAX_IMAGE_DIMENSION = 4096
    DEFAULT_MAX_IMAGE_PIXELS = 25_000_000
    SAFE_EXTRACTION_ERROR_DETAIL = "We couldn't process that photo right now."
    SAFE_OVERSIZE_ERROR_DETAIL = "Image is too large to process."

    EXTRACTION_PROMPT = """
      You are an AI assistant specialized in extracting family task lists and medication schedules from photos.

      The user has uploaded a photo of handwritten notes, a whiteboard, a to-do list, or medication directions for a pet or care recipient.
      Identify the task items that should become actionable tasks. If medication directions are visible, preserve the medication schedule facts exactly.

    Return ONLY valid JSON with this shape:
    {
        "suggested_kind": "tasks",
          "suggested_tasks": [
            {
                "title": "Task title",
                "notes": "Optional notes or context",
                "confidence": 0.95
            }
          ],
          "medications": [
              {
                  "medication_name": "Medication name",
                  "dosage_text": "Dose text exactly as shown",
                  "instructions": "Directions exactly as shown",
                  "next_due_text": "10PM",
                  "min_interval_hours": 8,
                  "max_interval_hours": 12,
                  "is_as_needed": true,
                  "confidence": 0.95
              }
          ],
          "care_subject_type": "pet or person when visible",
          "care_subject_name": "Name of the pet or person when visible",
          "preview_text": "Short human-readable preview",
          "processing_notes": "Optional notes about uncertain items"
      }

    Guidelines:
    - Prefer one task per item, even when the list is messy.
    - Keep titles short and actionable.
    - If a line is unclear, include your best guess and lower confidence.
      - If no task list is visible, return an empty suggested_tasks array.
      - For medication schedules, do not invent dose amounts or frequency. Leave fields blank or null when the photo is unclear.
      - For ranges like "every 8-12 hours", set min_interval_hours to 8 and max_interval_hours to 12.
      - For a visible "NEXT DOSE DUE: 10pm", keep next_due_text as "10pm".
      - Do not include extra commentary outside the JSON object.
      """

    @classmethod
    def _is_feature_enabled(cls, user: User | None) -> bool:
        if not getattr(settings, "FEATURE_FLAGS_ENABLED", False):
            return True

        family = get_default_family_for_user(user) if user is not None else None
        try:
            from openfeature.api import get_client
            from openfeature.evaluation_context import EvaluationContext

            evaluation_context = EvaluationContext(
                targeting_key=str(getattr(user, "id", "anonymous")),
                attributes={
                    "email": getattr(user, "email", ""),
                    "username": user.get_username() if user else "",
                },
            )
            client = get_client()
            return client.get_boolean_value(
                cls.FEATURE_FLAG_KEY,
                False,
                evaluation_context,
            )
        except Exception as exc:  # pragma: no cover - defensive guard
            logger.warning(
                "Task photo feature flag check failed, defaulting to disabled: %s",
                exc,
                **build_task_photo_log_context(
                    operation="task_photo_feature_flag_check",
                    user=user,
                    family=family,
                ),
            )
            return False

    @classmethod
    def _load_photo_bytes(cls, capture: InboxCapture) -> tuple[bytes, str, str]:
        if not capture.photo:
            raise TaskPhotoProcessingError("A photo is required for task extraction")

        with capture.photo.open("rb"):
            content = capture.photo.read()

        if not content:
            raise TaskPhotoProcessingError("Uploaded photo is empty")

        max_image_size = getattr(
            settings, "MAX_IMAGE_SIZE", cls.DEFAULT_MAX_IMAGE_SIZE_BYTES
        )
        if len(content) > max_image_size:
            raise TaskPhotoProcessingError(cls.SAFE_OVERSIZE_ERROR_DETAIL)

        max_dimension = getattr(
            settings, "TASK_PHOTO_MAX_IMAGE_DIMENSION", cls.DEFAULT_MAX_IMAGE_DIMENSION
        )
        max_pixels = getattr(
            settings, "TASK_PHOTO_MAX_IMAGE_PIXELS", cls.DEFAULT_MAX_IMAGE_PIXELS
        )
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("error", Image.DecompressionBombWarning)
                with Image.open(io.BytesIO(content)) as image:
                    width, height = image.size
                    if width > max_dimension or height > max_dimension:
                        raise TaskPhotoProcessingError(cls.SAFE_OVERSIZE_ERROR_DETAIL)
                    if width * height > max_pixels:
                        raise TaskPhotoProcessingError(cls.SAFE_OVERSIZE_ERROR_DETAIL)
                    image.verify()
                    content_type = Image.MIME.get(image.format or "", "image/jpeg")
        except (Image.DecompressionBombError, Image.DecompressionBombWarning) as exc:
            raise TaskPhotoProcessingError(cls.SAFE_OVERSIZE_ERROR_DETAIL) from exc
        except TaskPhotoProcessingError:
            raise
        except Exception as exc:
            raise TaskPhotoProcessingError("Uploaded photo is invalid.") from exc

        if not content_type:
            guessed = mimetypes.guess_type(capture.photo.name or "")[0]
            content_type = guessed or "image/jpeg"

        return content, content_type, capture.photo.name or "task-photo"

    @classmethod
    def _build_data_url(cls, content: bytes, content_type: str) -> str:
        encoded = base64.b64encode(content).decode("utf-8")
        return f"data:{content_type};base64,{encoded}"

    @classmethod
    def _strip_code_fence(cls, response_text: str) -> str:
        response_text = response_text.strip()
        if response_text.startswith("```"):
            lines = response_text.splitlines()
            if len(lines) >= 3:
                response_text = "\n".join(lines[1:-1]).strip()
        return response_text

    @classmethod
    def _extract_task_payload(cls, content: bytes, content_type: str) -> dict[str, Any]:
        from family_scheduler.ai_client import AIClient

        client = AIClient()
        response = client.chat.completions.create(
            model=get_workload_model("vision"),
            messages=[
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": cls.EXTRACTION_PROMPT},
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": cls._build_data_url(content, content_type)
                            },
                        },
                    ],
                }
            ],
            temperature=0.2,
        )

        response_text = cls._strip_code_fence(
            cast(str, response.choices[0].message.content or "")
        )
        try:
            parsed = cast(dict[str, Any], json.loads(response_text))
        except json.JSONDecodeError:
            truncated = response_text[:500]
            logger.error(
                "Task photo model response not valid JSON (truncated=%r)",
                truncated,
            )
            return {
                "success": False,
                "error": "Model response was not valid JSON.",
                "suggested_kind": "tasks",
                "suggested_tasks": [],
                "preview_text": "Photo capture ready for review",
                "processing_notes": response_text,
            }

        return parsed

    @classmethod
    def _normalize_payload(
        cls, extracted: dict[str, Any], *, capture: InboxCapture | None = None
    ) -> dict[str, Any]:
        raw_medications = (
            extracted.get("medications")
            or extracted.get("medication_entries")
            or extracted.get("suggested_medications")
        )
        raw_medication_text = (
            extracted.get("raw_text")
            or extracted.get("visible_text")
            or extracted.get("processing_notes")
            or getattr(capture, "raw_text", "")
        )
        if raw_medications or _extract_medications_from_text(raw_medication_text):
            if capture is None:
                raise TaskPhotoProcessingError(
                    "A capture is required for medication schedule extraction."
                )
            raw_payload = capture.raw_payload or {}
            medication_extracted = dict(extracted)
            medication_extracted.setdefault("raw_text", raw_medication_text)
            bundle = prepare_medication_task_bundle(
                family=capture.family,
                created_by=capture.created_by,
                source="photo",
                extracted=medication_extracted,
                care_subject_type=raw_payload.get("care_subject_type")
                or medication_extracted.get("care_subject_type"),
                care_subject_id=raw_payload.get("care_subject_id")
                or medication_extracted.get("care_subject_id"),
                care_subject_name=raw_payload.get("care_subject_name")
                or medication_extracted.get("care_subject_name"),
            )
            if processing_notes := str(extracted.get("processing_notes") or "").strip():
                bundle["processing_notes"] = processing_notes
            return bundle

        raw_tasks = extracted.get("suggested_tasks") or extracted.get("tasks") or []
        normalized_tasks: list[dict[str, Any]] = []

        for raw_task in raw_tasks:
            if isinstance(raw_task, str):
                title = raw_task.strip()
                notes = ""
                confidence = None
            elif isinstance(raw_task, dict):
                title = str(raw_task.get("title") or raw_task.get("name") or "").strip()
                notes = str(
                    raw_task.get("notes") or raw_task.get("description") or ""
                ).strip()
                confidence = raw_task.get("confidence")
                if isinstance(confidence, dict):
                    confidence = confidence.get("task") or confidence.get("title")
            else:
                continue

            if not title:
                continue

            if confidence is not None and not isinstance(confidence, (int, float)):
                confidence = None

            normalized_tasks.append(
                {
                    "title": title,
                    "notes": notes,
                    "confidence": confidence,
                }
            )

        preview_text = str(extracted.get("preview_text") or "").strip()
        if not preview_text:
            if normalized_tasks:
                preview_text = " | ".join(
                    task["title"] for task in normalized_tasks[:2]
                )[:140]
            else:
                preview_text = "Photo capture ready for review"

        payload = {
            "suggested_kind": "tasks",
            "suggested_tasks": normalized_tasks,
            "preview_text": preview_text,
        }
        processing_notes = str(extracted.get("processing_notes") or "").strip()
        if processing_notes:
            payload["processing_notes"] = processing_notes
        return payload

    @classmethod
    def process_capture(cls, capture: InboxCapture) -> dict[str, Any]:
        if not cls._is_feature_enabled(capture.created_by):
            return {
                "success": False,
                "error": "Task photo extraction is not enabled for your account",
            }

        capture.status = InboxCapture.Status.PROCESSING
        capture.save(update_fields=["status", "updated_at"])

        try:
            content, content_type, _photo_name = cls._load_photo_bytes(capture)
            extracted = cls._extract_task_payload(content, content_type)
            normalized = cls._normalize_payload(extracted, capture=capture)
            capture.normalized_payload = normalized
            capture.status = InboxCapture.Status.NEEDS_REVIEW
            capture.save(update_fields=["normalized_payload", "status", "updated_at"])
            return {"success": True, "data": normalized}
        except TaskPhotoProcessingError as exc:
            logger.warning(
                "Task photo processing failed: %s",
                exc,
                **build_task_photo_log_context(
                    operation="task_photo_process_capture",
                    capture=capture,
                ),
            )
            capture.status = InboxCapture.Status.CAPTURED
            capture.save(update_fields=["status", "updated_at"])
            return {"success": False, "error": str(exc), "status_code": 400}
        except Exception as exc:
            logger.error(
                "Unexpected task photo extraction failure: %s",
                exc,
                exc_info=True,
                **build_task_photo_log_context(
                    operation="task_photo_process_capture",
                    capture=capture,
                ),
            )
            capture.status = InboxCapture.Status.CAPTURED
            capture.save(update_fields=["status", "updated_at"])
            return {
                "success": False,
                "error": cls.SAFE_EXTRACTION_ERROR_DETAIL,
                "status_code": 500,
            }


def create_task_from_household_action(
