TIME_ONLY_RE = re.compile(
    r"\b(?P<hour>[01]?\d|2[0-3])(?::(?P<minute>[0-5]\d))?\s*(?P<ampm>a\.?m\.?|p\.?m\.?)?\b",
    re.IGNORECASE,
)
INVALID_COLON_TIME_RE = re.compile(
    r"\b(?:[01]?\d|2[0-3]):(?P<minute>\d{1,2})\s*(?:a\.?m\.?|p\.?m\.?)?\b",
    re.IGNORECASE,
)
MEDICATION_INTERVAL_RE = re.compile(
    r"\bevery\s+(?P<min>\d+(?:\.\d+)?)\s*(?:-|to)\s*(?P<max>\d+(?:\.\d+)?)\s*hours?\b"
    r"|\bevery\s+(?P<exact>\d+(?:\.\d+)?)\s*hours?\b",
    re.IGNORECASE,
)
MEDICATION_NEXT_DUE_RE = re.compile(
    r"\bnext\s+(?:dose\s+)?due\s*:?\s*(?P<due>[^\n.;]+)",
    re.IGNORECASE,
)
MEDICATION_HEADER_RE = re.compile(
    r"\b(?P<name>[A-Z][A-Za-z0-9()/-]*(?:\s+[A-Za-z0-9()/-]+){0,5}"
    r"\s+(?:\d+(?:\.\d+)?\s*(?:mg|mcg|g|ml)|tabs?|tablets?|caps?|capsules?|caplets?))\b",
    re.IGNORECASE,
)
MEDICATION_DOSE_RE = re.compile(
    r"\b(?:give|administer|take)\s+(?P<dose>.+?)"
    r"(?=\s+(?:by mouth|every|as needed|if needed|until|with|for)\b|[.;]|$)",
    re.IGNORECASE,
)
MEDICATION_AS_NEEDED_RE = re.compile(r"\b(?:as needed|if needed|prn)\b", re.IGNORECASE)


